import{_ as t,o as s,c as i,a2 as n}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Liste de Suggestions de Paramètres Étendus","description":"","frontmatter":{},"headers":[],"relativePath":"fr/98-扩展设定建议清单.md","filePath":"fr/98-扩展设定建议清单.md","lastUpdated":1789183869000}'),d={name:"fr/98-扩展设定建议清单.md"};function a(r,e,o,l,u,c){return s(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="liste-de-suggestions-de-parametres-etendus" tabindex="-1">Liste de Suggestions de Paramètres Étendus <a class="header-anchor" href="#liste-de-suggestions-de-parametres-etendus" aria-label="Permalink to &quot;Liste de Suggestions de Paramètres Étendus&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>98</td></tr><tr><td>Module</td><td>Annexes et matériaux de référence</td></tr><tr><td>Mots-clés principaux</td><td>paramètres étendus, suggestions de création, orientations des paramètres, ouverture, domaines à développer</td></tr></tbody></table><h2 id="i-notes" tabindex="-1">I. Notes <a class="header-anchor" href="#i-notes" aria-label="Permalink to &quot;I. Notes&quot;">​</a></h2><p>Ce document énumère les orientations et suggestions disponibles pour la création d&#39;extensions dans le système de paramètres de la Civilisation Symbiotique de l&#39;Ancre, visant à fournir inspiration et orientation aux créateurs de paramètres et à les aider à réaliser des extensions de paramètres précieuses dans le cadre existant. Cette liste est classée par module ; chaque orientation d&#39;extension comprend une description de l&#39;orientation, la valeur de l&#39;extension, le lien avec les paramètres existants et des suggestions de création. Il convient de souligner que cette liste n&#39;a qu&#39;une valeur consultative ; les créateurs peuvent s&#39;exprimer librement dans le respect de la cohérence des paramètres, et peuvent aussi développer des orientations entièrement nouvelles non couvertes par cette liste. Tous les paramètres étendus doivent passer l&#39;examen de la Liste d&#39;Auto-Vérification des Contradictions de Paramètres (document 97) avant d&#39;être officiellement intégrés.</p><h2 id="ii-orientations-d-extension-de-la-vision-du-monde-et-des-parametres-fondamentaux" tabindex="-1">II. Orientations d&#39;extension de la vision du monde et des paramètres fondamentaux <a class="header-anchor" href="#ii-orientations-d-extension-de-la-vision-du-monde-et-des-parametres-fondamentaux" aria-label="Permalink to &quot;II. Orientations d&#39;extension de la vision du monde et des paramètres fondamentaux&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Numéro</th><th>Orientation d&#39;extension</th><th>Valeur de l&#39;extension</th><th>Paramètres associés</th><th>Suggestions de création</th></tr></thead><tbody><tr><td>E01</td><td>Les existences au-delà de la limite de l&#39;univers</td><td>Explorer s&#39;il existe d&#39;autres univers ou des existences de dimension supérieure au-delà du réseau de lois de l&#39;Univers Hengyuan, fournissant une cosmologie plus grandiose au paramètre</td><td>Documents 00, 28</td><td>L&#39;existence d&#39;un « mur cosmique » peut être définie, ainsi que les histoires de très rares explorateurs franchissant le mur cosmique, posant les jalons d&#39;une future interaction interuniverselle</td></tr><tr><td>E02</td><td>L&#39;essence de la volonté cosmique</td><td>Explorer en profondeur si une « volonté cosmique » existe au fond du réseau de lois, et sa relation avec le mécanisme de l&#39;Ancre</td><td>Documents 00, 20</td><td>La volonté cosmique peut être définie comme un phénomène d&#39;auto-organisation non personnifié des lois plutôt qu&#39;une divinité spécifique, maintenant la position de « La réalité comme fondement »</td></tr><tr><td>E03</td><td>Les civilisations perdues de l&#39;ère pré-Ancre</td><td>Définir en détail les civilisations autrefois brillantes mais aujourd&#39;hui disparues de l&#39;ère pré-Ancre, enrichissant la profondeur historique</td><td>Documents 71, 93</td><td>Trois à cinq civilisations perdues représentatives peuvent être définies, chacune avec son système de culture, sa culture et sa cause de disparition uniques, fournissant des matériaux pour les paramètres archéologiques</td></tr><tr><td>E04</td><td>Les écoles philosophiques du concept de symbiose</td><td>Dans le grand cadre de « contre la prédation, pour la symbiose », définir les différentes interprétations du concept de symbiose par les différentes écoles philosophiques</td><td>Documents 04, 03</td><td>Des écoles telles que l&#39;« école symbiotique radicale », l&#39;« école symbiotique modérée », l&#39;« école symbiotique écologique » et l&#39;« école symbiotique technologique » peuvent être définies ; leurs confrontations idéelles peuvent devenir une importante tension narrative</td></tr></tbody></table><h2 id="iii-orientations-d-extension-du-systeme-de-culture" tabindex="-1">III. Orientations d&#39;extension du système de culture <a class="header-anchor" href="#iii-orientations-d-extension-du-systeme-de-culture" aria-label="Permalink to &quot;III. Orientations d&#39;extension du système de culture&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Numéro</th><th>Orientation d&#39;extension</th><th>Valeur de l&#39;extension</th><th>Paramètres associés</th><th>Suggestions de création</th></tr></thead><tbody><tr><td>E05</td><td>Les méthodes détaillées d&#39;un système unique</td><td>Développer en détail l&#39;un des Trois Cents Systèmes, y compris les méthodes de culture concrètes, les méthodes de percée de stade et les idées fausses courantes</td><td>Documents 10–19, 91</td><td>Il est suggéré de privilégier les Trois Fondations d&#39;Origine et les systèmes de la catégorie ingénierie appliquée étroitement liés à la technologie ; chaque document détaillé de système peut comprendre les étapes de culture, les formules d&#39;esprit, les besoins en ressources et les avertissements de risque</td></tr><tr><td>E06</td><td>Les schémas de combinaison de la culture conjointe</td><td>Étudier la compatibilité de la culture conjointe entre différents systèmes et concevoir des schémas de combinaison multisystèmes optimaux</td><td>Documents 10, 11–13</td><td>Des « combinaisons en or » (comme Itération Déductive + Principes Juridiques Spatiaux + Ingénierie Appliquée) et diverses combinaisons marginales peuvent être définies, analysant les avantages et les limites de chaque combinaison</td></tr><tr><td>E07</td><td>Les goulots d&#39;étranglement de culture et les méthodes de percée</td><td>Définir en détail les goulots d&#39;étranglement que chaque système peut rencontrer à différents stades, ainsi que les multiples méthodes pour les franchir</td><td>Documents 14, 19</td><td>Différents types de goulots d&#39;étranglement tels que l&#39;« épreuve du démon intérieur », la « barrière de lois » et l&#39;« obstacle d&#39;origine » peuvent être définis, avec les voies de percée correspondantes, ajoutant de la profondeur au processus de culture</td></tr><tr><td>E08</td><td>Les constitutions spéciales et l&#39;adaptation aux systèmes</td><td>Définir diverses constitutions spéciales (telles que le corps Dao inné, le corps d&#39;affinité élémentaire et le capteur de conscience puissant) et leurs relations d&#39;adaptation avec différents systèmes de culture</td><td>Documents 12, 51</td><td>Une « matrice d&#39;adaptation constitution–système » peut être conçue pour aider les créateurs à déterminer rapidement quels systèmes une constitution donnée est adaptée à cultiver</td></tr><tr><td>E09</td><td>La classification détaillée des ressources de culture</td><td>Classifier et définir en détail les diverses ressources nécessaires à la culture (trésors célestes et terrestres, cristaux d&#39;énergie, fragments de lois, etc.)</td><td>Documents 18, 65</td><td>Le niveau, le lieu d&#39;origine, la méthode de collecte, la méthode de conservation et les interdits d&#39;usage des ressources peuvent être définis, construisant une écologie complète des ressources de culture</td></tr></tbody></table><h2 id="iv-orientations-d-extension-du-systeme-social" tabindex="-1">IV. Orientations d&#39;extension du système social <a class="header-anchor" href="#iv-orientations-d-extension-du-systeme-social" aria-label="Permalink to &quot;IV. Orientations d&#39;extension du système social&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Numéro</th><th>Orientation d&#39;extension</th><th>Valeur de l&#39;extension</th><th>Paramètres associés</th><th>Suggestions de création</th></tr></thead><tbody><tr><td>E10</td><td>Les formes sociales concrètes des Cinq Typologies</td><td>Développer en détail les systèmes sociaux, les modèles économiques et les caractéristiques culturelles propres à chacune des Cinq Typologies de Civilisations Symbiotiques</td><td>Documents 30–35</td><td>Chaque typologie peut voir définir sa forme urbaine typique, sa structure familiale, son modèle éducatif et ses fêtes, rendant les Cinq Typologies chacune distinctive</td></tr><tr><td>E11</td><td>La planification et la construction des villes symbiotiques</td><td>Définir les concepts de planification, les styles architecturaux, les infrastructures et le zonage fonctionnel des villes de la civilisation symbiotique</td><td>Documents 39, 60</td><td>Différents types de formes urbaines tels que la « ville symbiotique verticale », la « ville à emboîtement écologique » et la « ville à pliage spatial » peuvent être conçus</td></tr><tr><td>E12</td><td>Le fonctionnement détaillé du système éducatif</td><td>Définir en détail le mécanisme de fonctionnement complet du système éducatif symbiotique, de l&#39;éducation préscolaire à l&#39;enseignement supérieur et à l&#39;éducation de culture</td><td>Documents 37, 43</td><td>Le système de programmes, les méthodes d&#39;évaluation, le système de mentors et les plans d&#39;éducation interraciaux peuvent être définis</td></tr><tr><td>E13</td><td>Le fonctionnement détaillé du système médical</td><td>Définir en détail le mécanisme de fonctionnement du système médical symbiotique, y compris la combinaison des soins médicaux conventionnels et des soins médicaux de culture</td><td>Documents 38, 44</td><td>Le système hospitalier, les procédures de remboursement de l&#39;assurance maladie, les normes spéciales des traitements de culture et les plans médicaux interraciaux peuvent être définis</td></tr><tr><td>E14</td><td>Le système de sécurité sociale et de protection sociale</td><td>Définir en détail le système de sécurité sociale de la civilisation symbiotique, y compris les retraites, le chômage et l&#39;assistance</td><td>Documents 32, 08</td><td>Les conditions de demande, les normes de versement, les sources de financement et les mécanismes de contrôle des prestations peuvent être définis</td></tr></tbody></table><h2 id="v-orientations-d-extension-du-droit-et-de-la-gouvernance" tabindex="-1">V. Orientations d&#39;extension du droit et de la gouvernance <a class="header-anchor" href="#v-orientations-d-extension-du-droit-et-de-la-gouvernance" aria-label="Permalink to &quot;V. Orientations d&#39;extension du droit et de la gouvernance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Numéro</th><th>Orientation d&#39;extension</th><th>Valeur de l&#39;extension</th><th>Paramètres associés</th><th>Suggestions de création</th></tr></thead><tbody><tr><td>E15</td><td>Les cas juridiques typiques</td><td>Rédiger des cas typiques jugés par le Tribunal Symbiotique, montrant l&#39;application du droit dans la pratique</td><td>Documents 40–49, 92</td><td>Des cas représentatifs tels que l&#39;« affaire de monopole des ressources de culture », l&#39;« affaire d&#39;indemnisation de pollution transplanaire » et l&#39;« affaire des droits des Entités Sombres de Remplacement » peuvent être rédigés</td></tr><tr><td>E16</td><td>Le système d&#39;autonomie locale</td><td>Définir en détail les systèmes d&#39;autonomie et le partage des compétences de chaque région stellaire et de chaque plan dans le cadre constitutionnel</td><td>Documents 40, 49</td><td>Les modèles d&#39;autonomie des différentes unités autonomes, leurs relations avec le gouvernement central et les procédures d&#39;élaboration des règlements d&#39;autonomie peuvent être définis</td></tr><tr><td>E17</td><td>Les systèmes électoral et démocratique</td><td>Définir en détail le système électoral des représentants de l&#39;Assemblée Délibérante de l&#39;Ancre et le mécanisme de décision démocratique</td><td>Documents 32, 49</td><td>Le découpage des circonscriptions, les qualifications des candidats, les procédures électorales, les modes de scrutin et les systèmes de mandat peuvent être définis</td></tr><tr><td>E18</td><td>Le mécanisme d&#39;application de la loi</td><td>Définir en détail le mécanisme d&#39;application de la loi, y compris les organes d&#39;exécution, les procédures d&#39;exécution et les mesures coercitives</td><td>Documents 48, 49</td><td>La structure organisationnelle, les pouvoirs d&#39;exécution, les procédures d&#39;exécution et les mécanismes de contrôle des organes d&#39;exécution peuvent être définis</td></tr></tbody></table><h2 id="vi-orientations-d-extension-de-la-vie-et-des-races" tabindex="-1">VI. Orientations d&#39;extension de la vie et des races <a class="header-anchor" href="#vi-orientations-d-extension-de-la-vie-et-des-races" aria-label="Permalink to &quot;VI. Orientations d&#39;extension de la vie et des races&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Numéro</th><th>Orientation d&#39;extension</th><th>Valeur de l&#39;extension</th><th>Paramètres associés</th><th>Suggestions de création</th></tr></thead><tbody><tr><td>E19</td><td>Les paramètres détaillés d&#39;une race unique</td><td>Développer en détail une race du Registre des Dix Mille Races, y compris les caractéristiques physiologiques, la structure sociale, les traditions culturelles et l&#39;évolution historique</td><td>Documents 50–52, 94</td><td>Il est suggéré de privilégier les races distinctives telles que la Race du Dragon (Lóng Zú), la Race de l&#39;Elfe (Jīnglíng Zú), la Race de la Machine (Jīxiè Zú) et la Race du Corps de Conscience (Yìshítǐ Zú) ; chaque race peut comprendre la langue, la religion, l&#39;art et les coutumes</td></tr><tr><td>E20</td><td>Les cas concrets de Vie Anomale</td><td>Définir des individus ou des groupes concrets de Vie Anomale, montrant l&#39;application pratique des trois types de procédures de traitement</td><td>Documents 53–54</td><td>Des cas tels que les « dériveurs du vide », la « vie de fragments temporels » et les « parasites de lois » peuvent être définis</td></tr><tr><td>E21</td><td>Les types concrets d&#39;Énergie Anomale</td><td>Définir en détail les caractéristiques, les sources, les usages et les méthodes de contrôle des diverses Énergies Anomales</td><td>Documents 55–56</td><td>Des types tels que l&#39;« énergie causale », l&#39;« énergie de conscience » et l&#39;« énergie de rémanence temporelle » peuvent être définis</td></tr><tr><td>E22</td><td>Les cas concrets d&#39;Entités Sombres de Remplacement</td><td>Définir des histoires individuelles concrètes d&#39;Entités Sombres de Remplacement, montrant l&#39;application pratique des Directives Éthiques des Deux Âmes et du traitement des quatre branches</td><td>Documents 57–59</td><td>Des histoires de cas de différents types d&#39;Entités Sombres de Remplacement peuvent être rédigées, explorant les dilemmes éthiques de la coexistence de deux âmes</td></tr><tr><td>E23</td><td>Les descendants de l&#39;intégration interraciale</td><td>Définir les caractéristiques et la culture des races mixtes nées de mariages entre différentes races</td><td>Documents 52, 77</td><td>Des races mixtes telles que les « demi-elfes », les « hommes-dragons » et les « humains bioniques mécaniques » peuvent être définies, explorant leur identité et leur fusion culturelle</td></tr></tbody></table><h2 id="vii-orientations-d-extension-de-la-technologie-et-de-l-energie" tabindex="-1">VII. Orientations d&#39;extension de la technologie et de l&#39;énergie <a class="header-anchor" href="#vii-orientations-d-extension-de-la-technologie-et-de-l-energie" aria-label="Permalink to &quot;VII. Orientations d&#39;extension de la technologie et de l&#39;énergie&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Numéro</th><th>Orientation d&#39;extension</th><th>Valeur de l&#39;extension</th><th>Paramètres associés</th><th>Suggestions de création</th></tr></thead><tbody><tr><td>E24</td><td>Les principes détaillés d&#39;une technologie unique</td><td>Fournir une analyse détaillée des principes d&#39;une technologie clé (telle que le Miroir de Réplication, l&#39;espace isolé et l&#39;ingénierie du Fruit Multiplicateur)</td><td>Documents 60–69, 63–64</td><td>L&#39;histoire du développement, les composants essentiels, le flux de travail, les limites techniques et les orientations d&#39;amélioration de la technologie peuvent être définis</td></tr><tr><td>E25</td><td>La classification détaillée des équipements de culture</td><td>Définir la classification, les fonctions, les niveaux et les modes d&#39;emploi des divers équipements auxiliaires de culture</td><td>Documents 61, 67</td><td>Des types d&#39;équipements tels que la « capsule de culture », le « détecteur de lois », le « convertisseur d&#39;énergie » et l&#39;« amplificateur de conscience » peuvent être définis</td></tr><tr><td>E26</td><td>Les paramètres détaillés du matériel d&#39;Ancre</td><td>Définir en détail la structure, les fonctions, la construction et la maintenance des installations matérielles d&#39;Ancre</td><td>Documents 20, 67</td><td>Les composants essentiels, l&#39;alimentation en énergie, le cycle de maintenance et le traitement des pannes des Ancres artificielles peuvent être définis</td></tr><tr><td>E27</td><td>La technologie de communication transplanaire</td><td>Définir en détail les principes techniques, les types d&#39;équipements, les protocoles de communication et les mécanismes de sécurité de la communication transplanaire</td><td>Documents 66, 81</td><td>Différentes méthodes de communication telles que la « communication par ondes d&#39;Ancre », la « communication par pliage spatial » et la « communication par résonance de conscience » peuvent être définies</td></tr></tbody></table><h2 id="viii-orientations-d-extension-de-l-histoire-et-des-evenements" tabindex="-1">VIII. Orientations d&#39;extension de l&#39;histoire et des événements <a class="header-anchor" href="#viii-orientations-d-extension-de-l-histoire-et-des-evenements" aria-label="Permalink to &quot;VIII. Orientations d&#39;extension de l&#39;histoire et des événements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Numéro</th><th>Orientation d&#39;extension</th><th>Valeur de l&#39;extension</th><th>Paramètres associés</th><th>Suggestions de création</th></tr></thead><tbody><tr><td>E28</td><td>Les récits détaillés des événements historiques majeurs</td><td>Fournir des récits historiques détaillés d&#39;un événement majeur de la chronologie</td><td>Documents 70–79, 93</td><td>Le déroulement complet d&#39;événements tels que l&#39;« événement d&#39;ouverture des Trois Cents Systèmes », la « mise en œuvre de la Stratégie d&#39;activation de 20 % » et la « première étape décisive de l&#39;élévation » peut être raconté en détail</td></tr><tr><td>E29</td><td>Les biographies des figures historiques</td><td>Rédiger des biographies détaillées pour les figures clés, enrichissant l&#39;épaisseur humaniste de l&#39;histoire</td><td>Document 95</td><td>Des biographies peuvent être rédigées pour des figures clés telles que « Xuánhéng Zǐ », « Gòngshēng Zǐ », « Lìxiàn Gōng » et « Sānbǎi Shī »</td></tr><tr><td>E30</td><td>L&#39;analyse hypothétique des tournants historiques</td><td>Analyser comment le développement de la civilisation symbiotique serait différent si un certain événement historique avait pris une autre voie</td><td>Documents 70–79</td><td>Des analyses hypothétiques telles que « si la Constitution Symbiotique n&#39;avait pas été adoptée » et « si la Stratégie d&#39;activation de 20 % avait échoué » peuvent être faites, montrant la contingence de l&#39;histoire</td></tr><tr><td>E31</td><td>Les comptes rendus détaillés des découvertes archéologiques</td><td>Définir les découvertes détaillées et les résultats de recherche d&#39;une certaine archéologie transplanaire</td><td>Documents 84–87</td><td>« La découverte archéologique d&#39;une certaine civilisation perdue » et « les résultats d&#39;archéologie par régression temporelle d&#39;un certain nœud historique clé » peuvent être définis</td></tr></tbody></table><h2 id="ix-orientations-d-extension-du-transplanaire-et-du-temps" tabindex="-1">IX. Orientations d&#39;extension du transplanaire et du temps <a class="header-anchor" href="#ix-orientations-d-extension-du-transplanaire-et-du-temps" aria-label="Permalink to &quot;IX. Orientations d&#39;extension du transplanaire et du temps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Numéro</th><th>Orientation d&#39;extension</th><th>Valeur de l&#39;extension</th><th>Paramètres associés</th><th>Suggestions de création</th></tr></thead><tbody><tr><td>E32</td><td>Les paramètres détaillés de plans spécifiques</td><td>Définir les paramètres de lois, les formes de civilisation, les environnements géographiques et les histoires d&#39;un plan spécifique</td><td>Documents 80, 81</td><td>Différents types de plans spécifiques tels que le « plan de haute magie », le « plan technologique », le « plan sauvage » et le « plan de conscience » peuvent être définis</td></tr><tr><td>E33</td><td>Les cas de diplomatie transplanaire</td><td>Définir des cas concrets de l&#39;établissement de relations diplomatiques entre la civilisation symbiotique et d&#39;autres civilisations de plans</td><td>Documents 81, 88</td><td>Des événements diplomatiques concrets tels que le premier contact, les négociations d&#39;établissement de relations, les échanges culturels et les accords commerciaux peuvent être définis</td></tr><tr><td>E34</td><td>Les cas concrets de régression temporelle</td><td>Définir le processus concret, les découvertes et les impacts d&#39;une certaine opération de régression temporelle</td><td>Documents 82–83, 89</td><td>Des cas tels que « la résolution par régression d&#39;un certain mystère historique » et « la reconstitution par régression d&#39;une certaine civilisation éteinte » peuvent être définis</td></tr><tr><td>E35</td><td>Les comptes rendus détaillés d&#39;événements de paradoxes temporels</td><td>Définir le processus complet d&#39;un certain événement de paradoxe temporel, y compris sa survenue, la réponse d&#39;urgence et la réparation causale</td><td>Document 89</td><td>Un compte rendu complet de traitement d&#39;un événement de paradoxe à petite échelle peut être rédigé, montrant le fonctionnement pratique des mécanismes de prévention et de contrôle</td></tr><tr><td>E36</td><td>Les conflits transplanaires et leur résolution</td><td>Définir les conflits entre la civilisation symbiotique et d&#39;autres civilisations de plans et le processus de résolution pacifique</td><td>Documents 81, 88</td><td>Différents types de cas de conflits transplanaires tels que les différends de ressources, les conflits culturels et les litiges frontaliers peuvent être définis</td></tr></tbody></table><h2 id="x-principes-de-creation-des-parametres-etendus" tabindex="-1">X. Principes de création des paramètres étendus <a class="header-anchor" href="#x-principes-de-creation-des-parametres-etendus" aria-label="Permalink to &quot;X. Principes de création des paramètres étendus&quot;">​</a></h2><p>Lors de la création de paramètres étendus, les principes suivants doivent être respectés :</p><ol><li><strong>Cohérence d&#39;abord</strong> : tous les paramètres étendus doivent rester logiquement cohérents avec les paramètres existants et passer l&#39;examen de la Liste d&#39;Auto-Vérification des Contradictions de Paramètres.</li><li><strong>La réalité comme fondement</strong> : les paramètres étendus doivent être raisonnablement déduits sur la base des lois objectives, évitant la pure spéculation et l&#39;effondrement des paramètres.</li><li><strong>Position symbiotique</strong> : les paramètres étendus doivent toujours maintenir la position centrale de lutte contre la prédation et de promotion de la symbiose, et ne doivent pas défendre les comportements prédateurs.</li><li><strong>Ouverture</strong> : les paramètres étendus doivent conserver un certain degré d&#39;ouverture, laissant de la place pour de futures extensions.</li><li><strong>Pertinence pratique</strong> : les paramètres étendus doivent avoir une valeur créative pratique, fournissant des matériaux utiles pour la création d&#39;histoires, la conception de jeux et la discussion théorique.</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La Liste de Suggestions de Paramètres Étendus est la « porte ouverte » du système de paramètres de la Civilisation Symbiotique de l&#39;Ancre. Elle montre que ce système de paramètres n&#39;est pas un produit fermé et achevé, mais un système vivant qui croît et s&#39;enrichit continuellement. Les trente-six orientations d&#39;extension ne sont qu&#39;un point de départ ; la véritable créativité des paramètres provient de l&#39;imagination et de l&#39;enthousiasme de chaque participant. Tant que le principe fondamental de la cohérence des paramètres est respecté, chaque extension précieuse deviendra un composant indispensable du récit grandiose de la Civilisation Symbiotique de l&#39;Ancre.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>97-设定矛盾自查表 (Liste d&#39;Auto-Vérification des Contradictions de Paramètres)</li><li>99-文档版本与维护说明 (Version des Documents et Notes de Maintenance)</li><li>96-常见问题FAQ (Foire Aux Questions (FAQ))</li></ul>',27)])])}const h=t(d,[["render",a]]);export{p as __pageData,h as default};
